#include <iostream>

int main() {
    int number{0};
    char ch{' '};
    if (std::cin >> number >> ch) {
        int d1 = number / 100;
        int d2 = (number / 10) % 10;
        int d3 = number % 10;
        int asciiCode = static_cast<int>(ch);

        std::cout << "Digits: " << d1 << "   " << d2 << "   " << d3 << "\n";
        std::cout << "Char: " << ch << " Code: " << asciiCode << "\n";
    }
    return 0;
}

#include <iostream>

int main() {
    int weightKg{0};
    int heightM{0};
    int num1{0};
    int num2{0};

    if (std::cin >> weightKg >> heightM >> num1 >> num2) {
        int bmi = (heightM > 0) ? (weightKg / (heightM * heightM)) : 0;
        std::cout << "BMI: " << bmi << "\n";

        if (num2 != 0 && num1 % num2 == 0) {
            std::cout << num1 << " is a multiple of " << num2 << "\n";
        } else {
            std::cout << num1 << " is not a multiple of " << num2 << "\n";
        }
    }
    return 0;
}
